function shp1010_query_rows(string $table,int $limit,int $tenantId=0,array $extra=[]): array {if(!shp1010_table_exists($table))return [];$cols=shp1010_columns($table);$w=[];$p=[];if($tenantId>0&&in_array('tenant_id',$cols,true)){$w[]='tenant_id=?';$p[]=$tenantId;}if(in_array('status',$cols,true))$w[]="status NOT IN ('deleted','inactive','disabled','rejected')";foreach($extra as $col=>$val)if(in_array($col,$cols,true)){$w[]="`$col`=?";$p[]=$val;}$order='id DESC';if(in_array('featured',$cols,true))$order='featured DESC,id DESC';elseif(in_array('is_featured',$cols,true))$order='is_featured DESC,id DESC';try{$q=db()->prepare('SELECT * FROM `'.$table.'`'.($w?' WHERE '.implode(' AND ',$w):'').' ORDER BY '.$order.' LIMIT '.max(1,min(24,$limit)));$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function shp1010_hero_ad(int $tenantId,int $id=0): array {if(!shp1010_table_exists('advertisements'))return [];$cols=shp1010_columns('advertisements');$w=[];$p=[];if($id>0){$w[]='id=?';$p[]=$id;}elseif(in_array('placement',$cols,true))$w[]="placement IN ('homepage_hero','hero','home_hero')";if($tenantId>0&&in_array('tenant_id',$cols,true)){$w[]='tenant_id=?';$p[]=$tenantId;}if(in_array('status',$cols,true))$w[]="status NOT IN ('inactive','deleted','disabled')";try{$q=db()->prepare('SELECT * FROM advertisements'.($w?' WHERE '.implode(' AND ',$w):'').' ORDER BY id DESC LIMIT 1');$q->execute($p);return $q->fetch()?:[];}catch(Throwable $e){return [];}}
